import {jointStopProbeSettings} from '../src/core/tasks/stop-settings.ts';
import {embody} from '../src/core/mind/mind.ts';
import {observeBody} from '../src/core/observation.ts';
import {physicalBody} from '../src/core/physical-body.ts';
import {clockSenses} from '../src/core/mind/senses.ts';
import {wholeBodyTracking} from '../src/core/control/whole-body.ts';
import {applyAction,checkedAction} from '../src/core/mind/actions.ts';
import {checkedMotionCommand} from '../src/core/control/tasks.ts';
export function hybridBody(built,world,make,options){
 const senses=clockSenses(world);let tracker;
 const embodied=embody(built,world,own=>{
  tracker=wholeBodyTracking(built,own.muscles,world.physics.gravity,[],[],{capacity:options.capacity,effortCost:options.effortCost,contact:{physics:world.physics,settings:{...options.contact,...(process.env.CF_LIFTOFF==='on'?{liftOff:{accelerationTolerance:1e-4}}:{})},dt:world.dt},jointStops:{settings:jointStopProbeSettings(true),dt:world.dt}});
  const model={channels:own.muscles.channels.map(c=>({name:c.name,min:c.dof.spec.min.value,max:c.dof.spec.max.value})),frames:[...built.segments.keys()].map(name=>({kind:'segment',name}))};
  const policy=make(model),observe=observeBody(built,own.muscles,world,senses);
  return{name:policy.name,state:{policy:policy.state,tracking:tracker.state},step(){const value=policy.step(observe(),world.dt);if(value.kind){applyAction(own.muscles,checkedAction(value,model.channels.length));tracker.state.contact.status='unconstrained';return;}const command=checkedMotionCommand(value,model);tracker.check(command);applyAction(own.muscles,{kind:'torque',torque:Array.from(tracker.track(command))});}};
 },senses);
 return Object.assign(physicalBody(embodied.own,world,senses,()=>embodied.mind.name,embodied.state,embodied.dispose),{report:()=>tracker.report()});
}

﻿import {Vector3,Quaternion} from '@babylonjs/core/Maths/math.vector.js';
import {felled} from '../research/core-rise-trials.mjs';
import {createMind} from '../src/core/mind/minds.ts';
import {FIGHTER} from '../src/core/mind/config.ts';
import {STAND_ORDERS} from '../src/core/mind/orders.ts';
import {RISE} from '../src/core/mind/rise/stages.ts';
import {hybridBody as createMotionBody} from './hybrid-body-production.mjs';
import {physicalReading} from '../src/core/observation.ts';
for(const model of [process.env.CF_MODEL]){
 let rest,bind;
 const fall=await felled({model,held:'empty',degrees:0,actuation:'directional'},(b,w)=>{const r=b.segments.get('lowerTrunk');rest={q:r.node.rotationQuaternion.clone(),p:r.node.position.clone(),centre:physicalReading(b)().centre.clone()};bind=Object.fromEntries(b.spec.joints.flatMap(j=>j.dofs.map(d=>[j.name+' '+d.positive,d.bind.value])));return createMind(b,w,FIGHTER,{name:'fall-start',orders:()=>STAND_ORDERS}).body;});
 const wasDown=fall.body.view.down;fall.body.dispose();
 const state={phase:'settle',stage:0,time:0,still:0,lie:'front',tries:0,furthest:-1,yaw:0};
 const body=createMotionBody(fall.built,fall.world,m=>({name:'motion-rise',state,step(obs,dt){
  state.time+=dt;const root=obs.segments.find(s=>s.name==='lowerTrunk');const current=new Quaternion(...root.rotation);const relative=current.multiply(Quaternion.Inverse(rest.q));
  const forward=new Vector3(0,0,1).applyRotationQuaternion(relative),left=new Vector3(-1,0,0).applyRotationQuaternion(relative);
  const readLie=()=>forward.y>.5?'back':forward.y<-.5?'front':left.y<0?'left':'right';
  if(state.phase==='settle'){const speed=Math.max(...obs.segments.map(s=>Math.hypot(...s.velocity)));state.still=speed<.1?state.still+dt:0;if(state.still>.5||state.time>3){state.lie=readLie();state.phase=state.lie==='front'?'rise':'roll';state.stage=0;state.time=0;state.tries++;const right=new Vector3(1,0,0).applyRotationQuaternion(relative);state.yaw=Math.atan2(-right.z,right.x);}}
  let sequence=state.phase==='roll'?RISE.roll[state.lie]:RISE.rise,stage=sequence?.[state.stage];
  if(state.phase==='settle')return{joints:[],frames:[],grips:[],supports:m.frames.filter(f=>f.kind==='segment').map(frame=>({frame,mode:'free'}))};
  if(state.phase==='stand')stage={kind:'bear',name:'stand',posture:'reference',on:[{limb:'foot.left',share:.5},{limb:'foot.right',share:.5}],height:1,pitch:0,seconds:.3,limit:60};
  const goals=m.channels.map(c=>({channel:c.name,angle:Math.max(c.min,Math.min(c.max,stage.posture==='reference'?0:(stage.posture[c.name]??0)-bind[c.name])),rate:0,acceleration:0,seconds:stage.kind==='pose'?.2:stage.seconds,weight:stage.kind==='pose'?1:.1}));
  let frames=[],centres=[],supports=m.frames.filter(f=>f.kind==='segment').map(frame=>({frame,mode:'free'})),ready=false;
  if(stage.kind==='pose'){ready=state.time>=stage.seconds;}
  else{
   const wanted=new Set();const aim=[0,0,0];for(const on of stage.on){const limb=RISE.limbs.find(l=>l.name===on.limb);wanted.add(limb.segment);if(limb.kind==='propped')wanted.add(limb.prop);const name=stage.overProp&&limb.kind==='propped'?limb.prop:limb.segment,part=obs.segments.find(s=>s.name===name);aim[0]+=on.share*part.centre[0];aim[2]+=on.share*part.centre[2];}
   supports=process.env.CF_ALL==='on'?[]:supports.filter(s=>!wanted.has(s.frame.name));
   const target=[root.position[0]+aim[0]-obs.centre[0],stage.height===null?root.position[1]:root.position[1]+stage.height*rest.centre.y-obs.centre[1],root.position[2]+aim[2]-obs.centre[2]];
   const q=stage.pitch===null?current:Quaternion.RotationAxis(Vector3.Up(),state.yaw).multiply(Quaternion.RotationAxis(Vector3.Right(),stage.pitch)).multiply(rest.q);
   frames=[{id:'root',frame:{kind:'segment',name:'lowerTrunk'},at:[0,0,0],orientation:{target:q.asArray(),velocity:[0,0,0],acceleration:[0,0,0],seconds:stage.seconds,weight:1}}];
   centres=[{id:"centre",frames:m.frames,translation:{target:[aim[0],stage.height===null?obs.centre[1]:stage.height*rest.centre.y,aim[2]],axes:stage.height===null?["x","z"]:["x","y","z"],velocity:[0,0,0],acceleration:[0,0,0],seconds:stage.seconds,weight:10}}];
   ready=(stage.height===null||Math.abs(stage.height*rest.centre.y-obs.centre[1])<.05)&&stage.on.every(on=>{const limb=RISE.limbs.find(l=>l.name===on.limb);return obs.contacts.some(c=>(c.segment===limb.segment||limb.kind==='propped'&&c.segment===limb.prop)&&c.fixed!==null&&c.impulse>0);})&&Math.hypot(aim[0]-obs.centre[0],aim[2]-obs.centre[2])<.05&&Math.hypot(...root.velocity)<.1&&(stage.pitch===null||1-Math.abs(Quaternion.Dot(q,current))<.003);
  }
  if(state.phase!=='stand'){
   if(ready){if(state.phase==='rise')state.furthest=Math.max(state.furthest,state.stage);state.stage++;state.time=0;if(state.stage>=sequence.length){state.phase=state.phase==='roll'?'settle':'stand';state.stage=0;state.still=0;}}
   else if(stage.kind==='bear'&&state.time>stage.limit){state.phase='settle';state.time=0;state.still=0;}
  }
  if(stage.kind==='pose')return{kind:'velocity',activation:m.channels.map(()=>1),velocity:goals.map((g,i)=>Math.max(-(stage.drive?.speed??3),Math.min(stage.drive?.speed??3,(g.angle-obs.joints[i].angle)/(stage.drive?.within??.2))))};return{joints:goals,frames,centres,grips:[],supports};
 }}),{items:[],grants:[],fixed:[],capacity:2,effortCost:1e-6,contact:{maxPoints:64,gap:.005,minUpNormal:.9,forceTolerance:1e-5,iterations:2048,absoluteTolerance:1e-7,relativeTolerance:1e-6}});
 try{let rejected=0,peak=0;for(let i=0;i<4800;i++){fall.world.step();if(body.report().contact?.status==='rejected')rejected++;peak=Math.max(peak,body.observe().height);if(i%600===599)console.log(JSON.stringify({model,liftOff:process.env.CF_LIFTOFF,allSupports:process.env.CF_ALL,seconds:(i+1)/120,wasDown,state,down:body.observe().down,height:body.observe().height,rejected,peak,report:body.report().errors}));}}finally{body.dispose();fall.dispose();}
}

