import {coreStand} from '../tests/harness/core-stand.mjs';
import {modelSpec} from '../src/core/human/spec.ts';
import {coupledDynamics} from '../src/core/build/coupled-dynamics.ts';
import {planarSupportPoints} from '../src/core/build/planar-support.ts';
import {preparePointContacts} from './contact-prepare.ts';
import {Quaternion} from '@babylonjs/core/Maths/math.vector.js';
import {embody} from '../src/core/mind/mind.ts';
import {applyAction} from '../src/core/mind/actions.ts';
import {boundedWork,linearWork,solveLinearTo,boundedLeastSquaresTo} from '../src/core/math/flat.ts';
import {nearJointStops} from '../src/core/control/joint-stops.ts';
const record=JSON.parse(fs.readFileSync('docs/reference/posture-limit-models.json','utf8')).rows.find(r=>r.job.engine==='rapier-coordinate'&&r.job.row==='fours').result;
const statics=await staticBody(undefined,'rapier-coordinate-coulomb');posed(statics,record.posture);
const stand=await coreStand(modelSpec('workshop-fighter'),{engine:'rapier-coordinate-coulomb',actuation:'directional'});
try{
 placeLike(statics,stand.built);
 const model=coupledDynamics(stand.built,stand.world.physics.gravity);
 const local=(s,p)=>{const d=p.map((v,i)=>v-s.frame.origin[i]);return ['x','y','z'].map(a=>s.frame[a].reduce((sum,v,i)=>sum+v*d[i],0));};
 const shapes=[...stand.built.segments.values()].flatMap(s=>s.rigid.shapes.map(shape=>{
  let converted;switch(shape.kind){
   case 'capsule': converted={kind:shape.kind,from:local(s,shape.from.value),to:local(s,shape.to.value),radius:shape.radius.value};break;
   case 'sphere': converted={kind:shape.kind,centre:local(s,shape.centre.value),radius:shape.radius.value};break;
   case 'box': converted={kind:shape.kind,centre:local(s,shape.centre.value),size:shape.size.value};break;
   case 'hull': converted={kind:shape.kind,points:shape.points.map(p=>local(s,p.value))};break;
  }return {segment:s,shape:converted};
 }));

 console.log(JSON.stringify({handGeometry:shapes.filter(s=>s.segment.spec.name.startsWith('hand')).map(({segment:s,shape})=>({name:s.spec.name,shape,points:planarSupportPoints(shape,s.node.position.asArray(),s.node.rotationQuaternion,[0,1,0],1)}))}));
 const segments=[...stand.built.segments.values()],com=s=>new Vector3(...s.body.massProperties.centre).applyRotationQuaternion(s.node.rotationQuaternion).add(s.node.position);
 const reference=segments.map(s=>({com:com(s),rotation:s.node.rotationQuaternion.clone(),position:s.node.position.clone()}));
 const n=model.channels,linear=linearWork(n),bounded=boundedWork(n),state={torque:new Array(n).fill(0),steps:0,rejected:0,drift:0};
 const body=embody(stand.built,stand.world,own=>({name:'forward-inverse-probe',state,step(){
   const contacts=shapes.flatMap(({segment:s,shape})=>planarSupportPoints(shape,s.node.position.asArray(),s.node.rotationQuaternion,[0,1,0],.001).filter(p=>p[1]<.005).map(point=>({body:s.body,point,normal:[0,1,0],normalVelocity:-Math.max(point[1],0)*120})));
  const stops=nearJointStops(stand.built,.001,1/120).map(s=>({row:s.row,minimumVelocity:s.rate+s.target/120,impulseTolerance:1e-10,velocityTolerance:1e-7}));

 const measured=state.predicted?segments.map((s,i)=>{const v=s.body.linearVelocityToRef(new Vector3()).asArray(),w=s.body.angularVelocityToRef(new Vector3()).asArray();return {name:s.spec.name,linear:Math.max(...v.map((v,k)=>Math.abs(v-state.predicted[i].linear[k]))),angular:Math.max(...w.map((v,k)=>Math.abs(v-state.predicted[i].angular[k])))}}):[];
 const torqueError=state.steps?Math.max(...state.torque.map((v,i)=>Math.abs(v-own.muscles.pulled[i]))):0;
 model.update();const clock=performance.now(),prepared=preparePointContacts(model,contacts,{dt:1/120,friction:.5,iterations:2048,impulseTolerance:1e-10,velocityTolerance:1e-7},stops);
 const scale=own.muscles.channels.map((c,i)=>Math.max(own.muscles.strength(i,-1),own.muscles.strength(i,1),1));
 const lower=scale.map((v,i)=>-own.muscles.strength(i,-1)/v),upper=scale.map((v,i)=>own.muscles.strength(i,1)/v);
 const targets=segments.map((s,i)=>{const p=com(s),v=s.body.linearVelocityToRef(new Vector3()).asArray(),w=s.body.angularVelocityToRef(new Vector3()).asArray(),q=reference[i].rotation.multiply(Quaternion.Inverse(s.node.rotationQuaternion)),sign=q.w<0?-1:1,rate=1/.3;
 return {point:p.asArray(),linear:v.map((x,k)=>x+(rate*rate*(reference[i].com.asArray()[k]-p.asArray()[k])-2*rate*x)/120),angular:w.map((x,k)=>x+(2*rate*rate*sign*[q.x,q.y,q.z][k]-2*rate*x)/120)};});
 const evaluate=x=>{const prediction=prepared.predict(x.map((v,i)=>v*scale[i]));
 const residual=segments.flatMap((s,i)=>{const start=model.pointVelocity(s.body,targets[i].point,prediction.projection.velocity),a=model.pointAcceleration(s.body,targets[i].point,prediction.acceleration),weight=s.spec.name==='lowerTrunk'?3:1;return [...a.linear.map((v,k)=>(start.linear[k]+v/120-targets[i].linear[k])*weight),...a.angular.map((v,k)=>(start.angular[k]+v/120-targets[i].angular[k])*.1*weight)];});
 return {prediction,residual,cost:residual.reduce((sum,v)=>sum+v*v,0)+1e-6*x.reduce((sum,v)=>sum+v*v,0)};};
 let x=state.torque.map((v,i)=>Math.max(lower[i],Math.min(upper[i],v/scale[i]))),current=evaluate(x),evaluations=1;
 for(let iteration=0;iteration<3;iteration++){
  const columns=[];for(let i=0;i<n;i++){const z=[...x],epsilon=.001;z[i]+=epsilon;const r=evaluate(z);evaluations++;columns.push(r.residual.map((v,k)=>(v-current.residual[k])/epsilon));}
  const H=new Float64Array(n*n),rhs=new Float64Array(n),unconstrained=new Float64Array(n),delta=new Float64Array(n);
  for(let i=0;i<n;i++){for(let j=0;j<n;j++)H[i*n+j]=columns[i].reduce((sum,v,k)=>sum+v*columns[j][k],0)+(i===j?1e-6:0);rhs[i]=-columns[i].reduce((sum,v,k)=>sum+v*current.residual[k],0)-1e-6*x[i];}
  solveLinearTo(linear,H,rhs,n,unconstrained);boundedLeastSquaresTo(bounded,H,unconstrained,lower.map((v,i)=>Math.max(v-x[i],-.25)),upper.map((v,i)=>Math.min(v-x[i],.25)),n,delta);
  let accepted=false;for(const length of [1,.5,.25,.125]){const z=x.map((v,i)=>v+length*delta[i]),candidate=evaluate(z);evaluations++;if(candidate.cost<current.cost){x=z;current=candidate;accepted=true;break;}}
  if(!accepted)break;
 }
 const accepted=current.prediction.status==='converged';if(!accepted)state.rejected++;
 state.predicted=segments.map((s,i)=>{const start=model.pointVelocity(s.body,targets[i].point,current.prediction.projection.velocity),a=model.pointAcceleration(s.body,targets[i].point,current.prediction.acceleration);return {linear:a.linear.map((v,k)=>start.linear[k]+v/120),angular:a.angular.map((v,k)=>start.angular[k]+v/120)};});
 state.torque=x.map((v,i)=>accepted?v*scale[i]:0);applyAction(own.muscles,{kind:'torque',torque:state.torque});state.steps++;
 state.drift=Math.max(state.drift,...segments.map((s,i)=>s.node.position.subtract(reference[i].position).length()));
 console.log(JSON.stringify({step:state.steps,handMotion:segments.flatMap((s,i)=>s.spec.name.startsWith('hand')?[{name:s.spec.name,predicted:state.predicted[i],actual:s.body.angularVelocityToRef(new Vector3()).asArray(),contacts:stand.world.physics.contactManifoldsOf(s.body,o=>o===null)}]:[]),worst:measured.sort((a,b)=>b.angular-a.angular).slice(0,3),torqueError,modelLinearError:Math.max(0,...measured.map(m=>m.linear)),modelAngularError:Math.max(0,...measured.map(m=>m.angular)),milliseconds:performance.now()-clock,evaluations,cost:current.cost,status:current.prediction.status,work:current.prediction.work,rejected:state.rejected,drift:state.drift,normalViolation:current.prediction.normalViolation,impulseResidual:current.prediction.impulseResidual,stopViolation:Math.max(0,...current.prediction.stops.map(s=>s.violation))}));
 }}));
 try{stand.step(2);console.log(JSON.stringify({final:segments.map((s,i)=>({name:s.spec.name,drift:s.node.position.subtract(reference[i].position).length()})).sort((a,b)=>b.drift-a.drift)}));}finally{body.dispose();}

}finally{stand.dispose();statics.dispose();}

