import {createDirectBody} from '../src/core/mind/direct.ts';
const pose=JSON.parse(fs.readFileSync('assets/research/posture-holds.json','utf8'))[0];
for(const degrees of [0,90,180,270]){
 const fall=await felled({model:'workshop-fighter',held:'empty',degrees,actuation:'directional'},(b,w)=>createMind(b,w,FIGHTER,{name:'fall-start',orders:()=>STAND_ORDERS}).body);
 const wasDown=fall.body.view.down;fall.body.dispose();
 const targets=Object.fromEntries([...fall.built.joints].flatMap(([name,j])=>j.dofs.map((d,i)=>[`${name} ${d.spec.positive}`,pose.placement.joints[name][i]])));
 const body=createDirectBody(fall.built,fall.world,{kind:'direct',targets,seconds:.01,speed:10,activation:1});
 try{for(let i=0;i<2400;i++){fall.world.step();if(i%600===599){const o=body.observe();console.log(JSON.stringify({degrees,wasDown,seconds:(i+1)/120,height:o.height,root:o.segments.find(s=>s.name==='lowerTrunk'),contacts:[...new Set(o.contacts.filter(c=>c.fixed!==null&&c.impulse>0).map(c=>c.segment))],maxAngleError:Math.max(...o.joints.map(j=>Math.abs(j.angle-targets[j.name])))}));}}}
 finally{body.dispose();fall.dispose();}
}

