 const fall=await felled({model:'workshop-fighter',held:'empty',degrees,actuation:'directional'},(b,w)=>createMind(b,w,FIGHTER,{name:'fall-start',orders:()=>STAND_ORDERS}).body);
 const wasDown=fall.body.view.down;fall.body.dispose();
 const rest=fall.built.segments.get('lowerTrunk').rest.clone();
 const targets=Object.fromEntries([...fall.built.joints].flatMap(([name,j])=>j.dofs.map((d,i)=>[`${name} ${d.spec.positive}`,pose.placement.joints[name][i]])));
 const bind=Object.fromEntries(fall.built.spec.joints.flatMap(j=>j.dofs.map(d=>[j.name+' '+d.positive,d.bind.value])));
 const state={phase:'settle',time:0,still:0,stage:0,lie:'front',attempts:0,holdSteps:0,peakHold:0};
 const body=createPolicyBody(fall.built,fall.world,m=>({name:'direct-entry',state,step(o,dt){
 state.time+=dt;const relative=new Quaternion(...o.segments.find(s=>s.name==='lowerTrunk').rotation).multiply(Quaternion.Inverse(rest));const forward=new Vector3(0,0,1).applyRotationQuaternion(relative),left=new Vector3(-1,0,0).applyRotationQuaternion(relative);
 const lie=forward.y>.5?'back':forward.y<-.5?'front':left.y<0?'left':'right';
 const contacts=new Set(o.contacts.filter(c=>c.fixed!==null&&c.impulse>0).map(c=>c.segment));
 if(state.phase==='settle'){state.still=Math.max(...o.segments.map(s=>Math.hypot(...s.velocity)))<.1?state.still+dt:0;if(state.still>.5||state.time>3){state.lie=lie;state.phase=lie==='front'?'fours':'roll';state.time=0;state.stage=0;state.attempts++;}}
 let stage=state.phase==='roll'?RISE.roll[state.lie][state.stage]:null;
 if(stage&&state.time>=stage.seconds){state.stage++;state.time=0;if(state.stage===RISE.roll[state.lie].length){state.phase='settle';state.still=0;}stage=state.phase==='roll'?RISE.roll[state.lie][state.stage]:null;}
 const holds=lie==='front'&&['hand.left','hand.right','shank.left','shank.right'].every(n=>contacts.has(n))&&!['upperTrunk','middleTrunk','lowerTrunk','head'].some(n=>contacts.has(n));state.holdSteps=holds?state.holdSteps+1:0;state.peakHold=Math.max(state.peakHold,state.holdSteps);
 if(state.phase==='fours'&&state.time>6&&!holds){state.phase='settle';state.time=0;state.still=0;}
 return {kind:'velocity',activation:m.channels.map(()=>state.phase==='settle'?0:1),velocity:m.channels.map((c,i)=>{const target=stage?Math.max(c.min,Math.min(c.max,(stage.posture[c.name]??0)-bind[c.name])):targets[c.name];const speed=seconds===.01?10:stage?.drive?.speed??3,within=seconds===.01?.01:stage?.drive?.within??seconds;return Math.max(-speed,Math.min(speed,(target-o.joints[i].angle)/within));})};
 }}));
 try{for(let i=0;i<4800;i++){fall.world.step();if(i%1200===1199){const o=body.observe();console.log(JSON.stringify({degrees,response:seconds,wasDown,seconds:(i+1)/120,state,height:o.height,contacts:[...new Set(o.contacts.filter(c=>c.fixed!==null&&c.impulse>0).map(c=>c.segment))]}));}}}
